from unittest.mock import patch

sys.path.insert(0, '/private/tmp/sdkbench-product-conformance-20261121/src')
from sdkbench.candidates.adapters import load_adapter, workflow_configuration
from sdkbench.candidates.applications import fixture
from sdkbench.p0 import Bundle
from sdkbench.p0.evaluators import routing
from flagquantum.compiler.optimization import _cz_blocks as blocks
from flagquantum.compiler.optimization import two_qubit_synthesis as synthesis
from flagquantum.compiler.lowering import target_legalization as target

BASE = '5a84f706ab9aeaab0ad3a5472bac292616fe39fe'
HARNESS = Path('/private/tmp/sdkbench-product-conformance-20261121')
NONCES = ['01'*32, 'e99f9400cba6007b9be3900694e5ea6440bf570cd07046e060ca7856689a47ad', '5a8e1eff6bad7ac6c3dd0f2cab4d63e392b504e26acb76b1be22ab61a4945573']
WORKFLOWS = ('flagquantum-ordinary-restored', 'flagquantum-target-artifact')
BUNDLE = Bundle(HARNESS/'docs/implementation')
assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=HARNESS,text=True,timeout=15).strip() == '9aa9260920984e2ca05bcb293abb885fccd9c144'
assert not subprocess.check_output(['git','status','--porcelain'],cwd=HARNESS,text=True,timeout=15).strip()
SOURCES = {}
for path in ('flagquantum/compiler/optimization/_cz_blocks.py', 'flagquantum/compiler/optimization/two_qubit_synthesis.py'):
    SOURCES[path] = {'baseline': subprocess.check_output(['git','show',BASE+':'+path],text=True,timeout=20), 'candidate': Path(path).read_text()}


def clone(source, name, namespace):
    node = next(node for node in ast.parse(source).body if isinstance(node, ast.FunctionDef) and node.name == name)
    namespace = dict(namespace)
    exec(compile(ast.Module(body=[node],type_ignores=[]),'<balanced-'+name+'>','exec'),namespace)
    return namespace[name]


FUNCTIONS = {}
for variant in ('baseline','candidate'):
    public = clone(SOURCES['flagquantum/compiler/optimization/two_qubit_synthesis.py'][variant], 'synthesize_two_qubit', vars(synthesis))
    namespace = {**vars(blocks), 'synthesize_two_qubit':public}
    candidate = clone(SOURCES['flagquantum/compiler/optimization/_cz_blocks.py'][variant], '_candidate', namespace)
    FUNCTIONS[variant] = {'public':public, 'candidate':candidate}


def adapter_for(workflow):
    configuration = workflow_configuration(workflow)
    return load_adapter(SimpleNamespace(configuration={'options':{'sdk':configuration['sdk'],'workflow':workflow,'compiler_options':configuration}}))


# Both variants subsequently replace the same warmed aliases for equal lifetimes.
for workflow in WORKFLOWS:
    adapter_for(workflow).execute('route',fixture(6,'qft','grid',NONCES[0]),11)
BINDS = []
for module_name,module in tuple(sys.modules.items()):
    if module is None or not module_name.startswith(('flagquantum.','benchmarks.')):
        continue
    for name,value in tuple(vars(module).items()):
        for label,original in (('public',synthesis.synthesize_two_qubit),('candidate',blocks._candidate)):
            if value is original:
                BINDS.append((module,name,label,original))


@contextlib.contextmanager
def selected(variant):
    try:
        with contextlib.ExitStack() as stack:
            for module,name,label,original in BINDS:
                assert vars(module)[name] is original
                stack.enter_context(patch.object(module,name,FUNCTIONS[variant][label]))
            yield
    finally:
        for module,name,label,original in BINDS:
            assert vars(module)[name] is original


def execute(variant, workflow, source, capture=False):
    adapter = adapter_for(workflow)
    stages = []
    original = target.optimize_native_blocks
    def record(*args,**kwargs):
        result = original(*args,**kwargs)
        if result is not None:
            stages.append({'rejection_counts':dict(result.rejection_counts),'rewrites':[row.to_dict() for row in result.rewrites]})
        return result
    with selected(variant), (patch.object(target,'optimize_native_blocks',record) if capture else contextlib.nullcontext()):
        started = time.perf_counter()
        payload = adapter.execute('route',source,11)
        elapsed = time.perf_counter()-started
    return payload, dict(adapter.audit), stages, elapsed


def accept(payload, source):
    width = source['n_qubits']
    assert payload['final_layout'] == list(range(width))
    case = BUNDLE.cases['ROUTE-GRID-08' if width == 8 else f'ROUTE-LINE-{width:02d}']
    return routing(payload,source,None,case,0)

